class LruCache {
  constructor(limit) { this.limit = limit; this.map = new Map(); }
  get(key) {
    if (!this.map.has(key)) return undefined;
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }
  set(key, value) {
    this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.limit) this.map.delete(this.map.keys().next().value);
  }
}
const cache = new LruCache(2);
cache.set('a', 1); cache.set('b', 2);
cache.get('a');
cache.set('c', 3);
console.log([...cache.map.keys()], cache.get('b'));

// A tiny fake clock so the timing is deterministic
let now = 0;
let timers = [];
const fakeSetTimeout = (fn, ms) => { const t = { fn, at: now + ms }; timers.push(t); return t; };
const fakeClearTimeout = (t) => { timers = timers.filter((x) => x !== t); };
const advanceTo = (time) => {
  timers.sort((a, b) => a.at - b.at);
  while (timers.length && timers[0].at <= time) { const t = timers.shift(); now = t.at; t.fn(); }
  now = time;
};

function debounce(fn, ms) {
  let t;
  return (arg) => { fakeClearTimeout(t); t = fakeSetTimeout(() => fn(arg), ms); };
}
const search = debounce((q) => console.log(`search "${q}" at ${now}`), 100);
search('j'); advanceTo(50);
search('ja'); advanceTo(120);
search('jav'); advanceTo(400);
search('java'); advanceTo(1000);

let now = 0;
function throttle(fn, ms) {
  let last = -Infinity;
  return (arg) => {
    if (now - last >= ms) { last = now; fn(arg); }
  };
}
const onScroll = throttle((y) => console.log(`handle y=${y} at ${now}`), 100);
for (const [t, y] of [[0, 0], [30, 40], [90, 120], [100, 150], [180, 260], [210, 300]]) {
  now = t;
  onScroll(y);
}

